445	// extrapolatedRate is a utility function for rate/increase/delta.
446	// It calculates the rate (allowing for counter resets if isCounter is true),
447	// extrapolates if the first/last sample is close to the boundary, and returns
448	// the result as either per-second (if isRate is true) or overall.
449	//
450	// Note: If the vector selector is smoothed or anchored, it will use the
451	// extendedRate or extendedHistogramRate function instead.
452	func extrapolatedRate(vals Matrix, args parser.Expressions, enh *EvalNodeHelper, isCounter, isRate bool) (Vector, annotations.Annotations) {
453		ms := args[0].(*parser.MatrixSelector)
454		vs := ms.VectorSelector.(*parser.VectorSelector)
455		if vs.Anchored || vs.Smoothed {
456			samples := vals[0]
457			if len(samples.Histograms) > 0 && len(samples.Floats) > 0 {
458				var annos annotations.Annotations
459				return enh.Out, annos.Add(annotations.NewMixedFloatsHistogramsWarning(getMetricName(samples.Metric), args[0].PositionRange()))
460			}
461			if len(samples.Histograms) > 0 {
462				return extendedHistogramRate(vals, args, enh, isCounter, isRate)
463			}
464			if len(samples.Floats) > 0 {
465				return extendedRate(vals, args, enh, isCounter, isRate)
466			}
467			// Not enough samples.
468			return enh.Out, nil
469		}
470	
471		var (
472			samples            = vals[0]
473			startTimestamps    []int64
474			rangeStart         = enh.Ts - durationMilliseconds(ms.Range+vs.Offset)
475			rangeEnd           = enh.Ts - durationMilliseconds(vs.Offset)
476			resultFloat        float64
477			resultHistogram    *histogram.FloatHistogram
478			firstT, lastT      int64
479			numSamplesMinusOne int
480			annos              annotations.Annotations
481		)
482	
483		// Drop this vector element and return a warning if this rate window contains mixed float and histogram samples.
484		if len(samples.Histograms) > 0 && len(samples.Floats) > 0 {
485			return enh.Out, annos.Add(annotations.NewMixedFloatsHistogramsWarning(getMetricName(samples.Metric), args[0].PositionRange()))
486		}
487	
488		// To calculate a rate, we normally need at least two float or two histogram samples. However,
489		// we can calculate rate with a single sample as long as there's a start timestamp reset inside the window.
490		switch {
491		case len(samples.Histograms) > 0:
492			numSamplesMinusOne = len(samples.Histograms) - 1
493			firstT = samples.Histograms[0].T
494			lastT = samples.Histograms[numSamplesMinusOne].T
495			var newAnnos annotations.Annotations
496			if enh.StartTimestamps != nil {
497				startTimestamps = enh.StartTimestamps.Histograms
498			}
499			if len(samples.Histograms) > 1 {
500				resultHistogram, newAnnos = histogramRate(samples.Histograms, startTimestamps, isCounter,
501					samples.Metric, args[0].PositionRange())
502				annos.Merge(newAnnos)
503				if resultHistogram == nil {
504					// The histograms are not compatible with each other.
505					return enh.Out, annos
506				}
507			}
508		case len(samples.Floats) > 0:
509			numSamplesMinusOne = len(samples.Floats) - 1
510			firstT = samples.Floats[0].T
511			lastT = samples.Floats[numSamplesMinusOne].T
512			resultFloat = samples.Floats[numSamplesMinusOne].F - samples.Floats[0].F
513			if !isCounter {
514				break
515			}
516			// Handle counter resets:
517			if enh.StartTimestamps != nil {
518				startTimestamps = enh.StartTimestamps.Floats
519			}
520			var overlapDetected bool
521			for i, currPoint := range samples.Floats[1:] {
522				prevPoint := samples.Floats[i]
523				// Warn once per series if start timestamp overlap detected.
524				if !overlapDetected && i+1 < len(startTimestamps) {
525					if checkStartTimeOverlap(startTimestamps[i], prevPoint.T, startTimestamps[i+1]) {
526						// Extract metric name only when needed.
527						annos.Add(annotations.NewStartTimeOverlapWarning(getMetricName(samples.Metric), args[0].PositionRange()))
528						overlapDetected = true
529					}
530				}
531				if currPoint.F < prevPoint.F || (i+1 < len(startTimestamps) && isStartTimestampReset(startTimestamps[i], prevPoint.T, startTimestamps[i+1], currPoint.T)) {
532					resultFloat += prevPoint.F
533				}
534			}
535		default:
536			// TODO: add RangeTooShortWarning
537			return enh.Out, annos
538		}
539	
540		// Duration between first/last samples and boundary of range.
541		durationToStart := float64(firstT-rangeStart) / 1000
542		durationToEnd := float64(rangeEnd-lastT) / 1000
543	
544		sampledInterval := float64(lastT-firstT) / 1000
545		var averageDurationBetweenSamples float64
546		if numSamplesMinusOne > 0 {
547			averageDurationBetweenSamples = sampledInterval / float64(numSamplesMinusOne)
548		}
549		extrapolationThreshold := averageDurationBetweenSamples * 1.1
550	
551		if sts := startTimestamps; isCounter && len(sts) > 0 && sts[0] != 0 && sts[0] > rangeStart && sts[0] < firstT {
552			// Take the first sample in the range and check whether its ST points inside the range
553			// (while also having a sensible value). If yes, we assume that there is a zero-value sample
554			// at the time of ST, and use that instead of extrapolating towards left side.
555			//
556			// Note that the rangeStart is exclusive, thus ST=rangeStart would be outside the range.
557			//
558			// Also note that when there's a single sample, we lose extrapolation to the right, because
559			// we need at least two samples to calculate average duration between samples, which leads
560			// to extrapolation threshold being 0.
561			durationToStart = 0
562			sampledInterval = float64(lastT-sts[0]) / 1000
563			if len(samples.Floats) > 0 {
564				resultFloat += samples.Floats[0].F
565			} else if len(samples.Histograms) > 0 {
566				if resultHistogram == nil {
567					resultHistogram = samples.Histograms[0].H.Copy()
568				} else if !addHistogramWithAnnotations(resultHistogram, samples.Histograms[0].H, &annos, getMetricName(samples.Metric), args[0].PositionRange()) {
569					return enh.Out, annos
570				}
571			}
572		} else if numSamplesMinusOne == 0 {
573			// There's a single sample, and we do not have suitable ST to calculate the increase. Return nothing.
574			return enh.Out, annos
575		} else {
576			// If samples are close enough to the (lower or upper) boundary of the
577			// range, we extrapolate the rate all the way to the boundary in
578			// question. "Close enough" is defined as "up to 10% more than the
579			// average duration between samples within the range", see
580			// extrapolationThreshold below. Essentially, we are assuming a more or
581			// less regular spacing between samples, and if we don't see a sample
582			// where we would expect one, we assume the series does not cover the
583			// whole range, but starts and/or ends within the range. We still
584			// extrapolate the rate in this case, but not all the way to the
585			// boundary, but only by half of the average duration between samples
586			// (which is our guess for where the series actually starts or ends).
587	
588			if durationToStart >= extrapolationThreshold {
589				durationToStart = averageDurationBetweenSamples / 2
590			}
591			if isCounter {
592				// Counters cannot be negative. If we have any slope at all
593				// (i.e. resultFloat went up), we can extrapolate the zero point
594				// of the counter. If the duration to the zero point is shorter
595				// than the durationToStart, we take the zero point as the start
596				// of the series, thereby avoiding extrapolation to negative
597				// counter values.
598				durationToZero := durationToStart
599				if resultFloat > 0 &&
600					len(samples.Floats) > 0 &&
601					samples.Floats[0].F >= 0 {
602					durationToZero = sampledInterval * (samples.Floats[0].F / resultFloat)
603				} else if resultHistogram != nil &&
604					resultHistogram.Count > 0 &&
605					len(samples.Histograms) > 0 &&
606					samples.Histograms[0].H.Count >= 0 {
607					durationToZero = sampledInterval * (samples.Histograms[0].H.Count / resultHistogram.Count)
608				}
609				if durationToZero < durationToStart {
610					durationToStart = durationToZero
611				}
612			}
613		}
614	
615		if durationToEnd >= extrapolationThreshold {
616			durationToEnd = averageDurationBetweenSamples / 2
617		}
618	
619		factor := 1.0
620		if sampledInterval != 0 {
621			factor = (sampledInterval + durationToStart + durationToEnd) / sampledInterval
622		}
623		if isRate {
624			factor /= ms.Range.Seconds()
625		}
626		if resultHistogram == nil {
627			resultFloat *= factor
628		} else {
629			resultHistogram.Mul(factor)
630		}
631	
632		return append(enh.Out, Sample{F: resultFloat, H: resultHistogram}), annos
633	}
