635	// histogramRate is a helper function for extrapolatedRate. It requires
636	// points[0] to be a histogram. It returns nil if any other Point in points is
637	// not a histogram or there are incompatibilities between histograms, and a warning
638	// wrapped in an annotation in that case. Otherwise, it returns the calculated histogram,
639	// and potentially some annotations.
640	func histogramRate(
641		points []HPoint,
642		startTimestamps []int64,
643		isCounter bool,
644		labels labels.Labels,
645		pos posrange.PositionRange,
646	) (*histogram.FloatHistogram, annotations.Annotations) {
647		var (
648			prev               = points[0].H
649			usingCustomBuckets = prev.UsesCustomBuckets()
650			last               = points[len(points)-1].H
651			annos              annotations.Annotations
652		)
653	
654		if last == nil {
655			return nil, annos.Add(annotations.NewMixedFloatsHistogramsWarning(getMetricName(labels), pos))
656		}
657	
658		// We check for gauge type histograms in the loop below, but the loop
659		// below does not run on the first and last point, so check the first
660		// and last point now.
661		if isCounter && (prev.CounterResetHint == histogram.GaugeType || last.CounterResetHint == histogram.GaugeType) {
662			// TODO(start-timestamps): for delta histograms, we plan to use Gauge counter reset hint,
663			// while the reset will be indicated via a start timestamp. This will be an expected usage pattern,
664			// thus we should not be returning the following warning. When addressing this, also check
665			// other places where this warning is being emitted.
666			annos.Add(annotations.NewNativeHistogramNotCounterWarning(getMetricName(labels), pos))
667		}
668	
669		// Null out the 1st sample if there is a counter reset between the 1st
670		// and 2nd. In this case, we want to ignore any incompatibility in the
671		// bucket layout of the 1st sample because we do not need to look at it.
672		if isCounter {
673			second := points[1].H
674			if second != nil && (len(startTimestamps) > 1 && isStartTimestampReset(startTimestamps[0], points[0].T, startTimestamps[1], points[1].T) || second.DetectReset(prev)) {
675				prev = &histogram.FloatHistogram{}
676				prev.Schema = second.Schema
677				prev.CustomValues = second.CustomValues
678				usingCustomBuckets = second.UsesCustomBuckets()
679			}
680		}
681	
682		if last.UsesCustomBuckets() != usingCustomBuckets {
683			return nil, annos.Add(annotations.NewMixedExponentialCustomHistogramsWarning(getMetricName(labels), pos))
684		}
685	
686		// First iteration to find out two things:
687		// - What's the smallest relevant schema?
688		// - Are all data points histograms?
689		minSchema := min(last.Schema, prev.Schema)
690		for _, currPoint := range points[1 : len(points)-1] {
691			curr := currPoint.H
692			if curr == nil {
693				return nil, annotations.New().Add(annotations.NewMixedFloatsHistogramsWarning(getMetricName(labels), pos))
694			}
695			if !isCounter {
696				continue
697			}
698			if curr.CounterResetHint == histogram.GaugeType {
699				annos.Add(annotations.NewNativeHistogramNotCounterWarning(getMetricName(labels), pos))
700			}

